// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The simple topics (model topics@1): the heading, a description and the topics as a list on a card surface,
 * each with a short label (a badge), the title (a link when the topic has an address) and a line. Axes: layout
 * (cards: columns, rows: one under the other), cols (2, 3 columns of the cards).
 */
import { For, type JSX } from "solid-js";
import { Badge, Block, Container, LinkPlain, List, ListItem, Stack, Text, Title } from "../compose";
import { cn, urlOf } from "../utils";
import type { TopicItem } from "./topics-simple.types";

export type TopicsSimpleProps = {
  id: string;
  title: string;
  description?: string;
  items: TopicItem[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  align?: "start" | "center" | "end";
  layout?: "cards" | "rows";
  cols?: "2" | "3";
  landmarkLabel?: string;
};

export function TopicsSimple({
  id,
  title,
  description = "",
  items,
  level = 2,
  padding = "standard",
  align = "center",
  layout = "cards",
  cols = "3",
  landmarkLabel,
}: TopicsSimpleProps) {
  const titleId = id + "-title";
  const column =
    (align as string) === "center" ? "center"
    : (align as string) === "end" ? "end"
    : "start";
  const textAlign =
    (align as string) === "center" ? "text-center"
    : (align as string) === "end" ? "text-end"
    : "text-start";
  const itemsAlign =
    (align as string) === "center" ? "items-center"
    : (align as string) === "end" ? "items-end"
    : "items-start";
  const selfAlign =
    (align as string) === "center" ? "self-center"
    : (align as string) === "end" ? "self-end"
    : "";
  const grid =
    (layout as string) === "rows" ? "mx-auto w-full max-w-3xl"
    : (cols as string) === "2" ? "md:grid-cols-2"
    : "md:grid-cols-3";
  const item = ((layout as string) === "rows") ? "md:flex-row md:items-center md:gap-6" : "";
  return (
    <Block
      tag="section"
      class={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="topics-simple"
    >
      <Container class="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" align={column} class={cn("max-w-2xl", selfAlign)}>
            <Title as={level} size="3xl" weight="bold" class={cn("tracking-tight", textAlign)} id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" class={cn("text-muted-foreground", textAlign)}>
                {description}
              </Text>
            ) : null}
          </Stack>
          <List tag="ul" class={cn("m-0 w-full list-none p-0", cn("grid grid-cols-1 gap-6", grid))}>
            <For each={items ?? []}>{(t) => (
              <ListItem
                class={cn(
                  "flex flex-col items-start gap-4 rounded bg-card p-6 text-card-foreground border border-border",
                  item
                )}
                data-slot="topic"
              >
                <Badge variant="secondary">
                  {t.label}
                </Badge>
                <Stack gap="2" align="start">
                  {t.href ? (
                    <LinkPlain href={urlOf(t.href)} class="hover:text-primary">
                      <Title as={(level + 1)} size="lg" weight="semibold" class="text-start">
                        {t.title}
                      </Title>
                    </LinkPlain>
                  ) : (
                    <Title as={(level + 1)} size="lg" weight="semibold" class="text-start">
                      {t.title}
                    </Title>
                  )}
                  {t.description ? (
                    <Text size="sm" class={cn("text-muted-foreground", "text-start")}>
                      {t.description}
                    </Text>
                  ) : null}
                </Stack>
              </ListItem>
            )}</For>
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

